import{_ as a,o as t,c as r,a2 as o}from"./chunks/framework.BXA5Pi9t.js";const c=JSON.parse('{"title":"Ceph Performance Meeting 2021-05-27","description":"","frontmatter":{"title":"Ceph Performance Meeting 2021-05-27","date":"2021-05-27T00:00:00.000Z","updated":"2021-05-28T00:00:00.000Z","tags":["Ceph","分布式存储","性能优化","BlueFS","FFS改进"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2021/Ceph_Performance_Meeting_2021-05-27.md","filePath":"posts/2021/Ceph_Performance_Meeting_2021-05-27.md","lastUpdated":1780459816000}'),l={name:"posts/2021/Ceph_Performance_Meeting_2021-05-27.md"};function n(i,e,s,h,u,d){return t(),r("div",null,[...e[0]||(e[0]=[o('<h3 id="会议纪要" tabindex="-1">会议纪要 <a class="header-anchor" href="#会议纪要" aria-label="Permalink to &quot;会议纪要&quot;">​</a></h3><h4 id="关键细节" tabindex="-1">关键细节 <a class="header-anchor" href="#关键细节" aria-label="Permalink to &quot;关键细节&quot;">​</a></h4><ul><li><strong>性能相关PR</strong>: 本次会议讨论了多个性能相关的问题，包括管理器实现的TTL缓存、D3N缓存更改、RocksDB优化、压缩Blob大小设置、ISC 21提交等。</li><li><strong>RocksDB优化</strong>: Gabby正在移除RocksDB中的分配，但在笔记本电脑上遇到bug，测试集群中未出现。</li><li><strong>压缩Blob大小设置</strong>: Adam的PR将压缩Blob大小设置为64KB，已获批准，但需要进一步测试和改进。</li><li><strong>ISC 21提交</strong>: 讨论是否为国际超级计算机会议提交FFS（Fast File System）改进，尽管之前的测试结果不理想，但仍有改进空间。</li><li><strong>BlueFS锁优化</strong>: Adam正在尝试将BlueFS的大锁分解为更小的锁，以提高性能。</li></ul><h4 id="讨论的主要议题" tabindex="-1">讨论的主要议题 <a class="header-anchor" href="#讨论的主要议题" aria-label="Permalink to &quot;讨论的主要议题&quot;">​</a></h4><ul><li><strong>性能改进</strong>: 讨论了多个性能相关的PR，包括TTL缓存、D3N缓存更改、RocksDB优化等。</li><li><strong>ISC 21提交</strong>: 讨论了是否继续提交FFS改进到国际超级计算机会议。</li><li><strong>BlueFS锁优化</strong>: 讨论了将BlueFS的大锁分解为更小的锁的可能性。</li></ul><h4 id="决定的事项" tabindex="-1">决定的事项 <a class="header-anchor" href="#决定的事项" aria-label="Permalink to &quot;决定的事项&quot;">​</a></h4><ul><li><strong>性能相关PR</strong>: 确认了多个性能相关的PR的进展，包括RocksDB优化、压缩Blob大小设置等。</li><li><strong>ISC 21提交</strong>: 决定继续探索FFS的改进，并可能在未来的会议上提交。</li><li><strong>BlueFS锁优化</strong>: 决定继续进行BlueFS锁优化的工作。</li></ul><h4 id="后续的行动计划" tabindex="-1">后续的行动计划 <a class="header-anchor" href="#后续的行动计划" aria-label="Permalink to &quot;后续的行动计划&quot;">​</a></h4><ul><li><strong>性能相关PR</strong>: 继续跟踪和测试性能相关的PR，确保它们能够安全地合并到主分支。</li><li><strong>ISC 21提交</strong>: 继续进行FFS的改进工作，包括性能测试和优化。</li><li><strong>BlueFS锁优化</strong>: 继续进行BlueFS锁优化的工作，确保更改不会破坏现有功能。</li></ul><h4 id="其他事项" tabindex="-1">其他事项 <a class="header-anchor" href="#其他事项" aria-label="Permalink to &quot;其他事项&quot;">​</a></h4><ul><li><strong>纪念日周末</strong>: 提醒美国团队成员即将到来的纪念日周末，并祝愿大家有一个愉快的假期。</li></ul><h3 id="结论" tabindex="-1">结论 <a class="header-anchor" href="#结论" aria-label="Permalink to &quot;结论&quot;">​</a></h3><p>本周会议主要集中在Ceph的性能优化和未来的工作计划上，特别是关于FFS的改进和BlueFS的锁优化。团队将继续跟踪和测试相关的PR，并确保所有更改都能够安全地合并到主分支。</p>',13)])])}const _=a(l,[["render",n]]);export{c as __pageData,_ as default};
